function allSentences(s: string, words: string[]): string[] {
  const dict = new Set(words);
  let longest = 0;
  for (const w of words) longest = Math.max(longest, w.length);
  const memo = new Map<number, string[]>();
  const f = (i: number): string[] => {
    if (i === s.length) return [""];
    const hit = memo.get(i);
    if (hit) return hit;
    const res: string[] = [];
    for (let end = i + 1; end <= Math.min(s.length, i + longest); end++) {
      const w = s.slice(i, end);
      if (!dict.has(w)) continue;
      for (const tail of f(end)) res.push(tail ? w + " " + tail : w);
    }
    memo.set(i, res);
    return res;
  };
  return f(0);
}

